80	function getUnixTimestampSeconds(): number {
81	  return Math.floor(Date.now() / 1000);
82	}
83	
84	/**
85	 * Creates `MLCEngine`, and loads `modelId` onto WebGPU.
86	 *
87	 * Equivalent to `new webllm.MLCEngine().reload(...)`.
88	 *
89	 * @param modelId model_id of the model to load, either string or string[]. When multiple models
90	 *   are provided, we load all models sequentially. Each modelId needs to either be in
91	 *   `webllm.prebuiltAppConfig`, or in `engineCOnfig.appConfig`.
92	 * @param engineConfig Optionally configures the engine, see `webllm.MLCEngineConfig`.
93	 * @param chatOpts Extra options to optionally override the `mlc-chat-config.json` of `modelId`.
94	 *   The size of which needs to match that of `modelId`; chatOpts[i] will be used for modelId[i].
95	 * @returns An initialized `WebLLM.MLCEngine` with `modelId` loaded.
96	 * @throws Throws error when device lost (mostly due to OOM); users should re-call `CreateMLCEngine()`,
97	 *   potentially with a smaller model or smaller context window size.
98	 */
99	export async function CreateMLCEngine(
100	  modelId: string | string[],
101	  engineConfig?: MLCEngineConfig,
102	  chatOpts?: ChatOptions | ChatOptions[],
103	): Promise<MLCEngine> {
104	  const engine = new MLCEngine(engineConfig);
105	  await engine.reload(modelId, chatOpts);
106	  return engine;
107	}
108	
109	/**
110	 * The main interface of MLCEngine, which loads a model and performs tasks.
111	 *
112	 * You can either initialize one with `webllm.CreateMLCEngine(modelId)`, or
113	 * `webllm.MLCEngine().reload(modelId)`.
114	 */
115	export class MLCEngine implements MLCEngineInterface {
116	  // APIs
117	  /** For chat.completions.create() */
118	  public chat: API.Chat;
119	  /** For completions.create() */
120	  public completions: API.Completions;
121	  /** For embeddings.create() */
122	  public embeddings: API.Embeddings;
123	
124	  // Maps to maintain states of loaded model(s)
125	  /** Maps each loaded model's modelId to its pipeline */
126	  private loadedModelIdToPipeline: Map<
127	    string,
128	    LLMChatPipeline | EmbeddingPipeline
129	  >;
130	  /** Maps each loaded model's modelId to its chatConfig */
131	  private loadedModelIdToChatConfig: Map<string, ChatConfig>;
132	  /** Maps each loaded model's modelId to its modelType */
133	  private loadedModelIdToModelType: Map<string, ModelType>;
134	  /** Maps each loaded model's modelId to a lock. Ensures
135	   * each model only processes one request at at time.
136	   */
137	  private loadedModelIdToLock: Map<string, CustomLock>;
138	
139	  // Others
140	  private logger: (msg: string) => void = log.info;
141	  private logitProcessorRegistry?: Map<string, LogitProcessor>;
142	  private initProgressCallback?: InitProgressCallback;
143	  private appConfig: AppConfig;
144	
145	  // Signals and flags
146	  private interruptSignal = false;
147	  private deviceLostIsError = true; // whether device.lost is due to actual error or model reload
148	  private reloadController: AbortController | undefined;
149	
150	  constructor(engineConfig?: MLCEngineConfig) {
151	    this.loadedModelIdToPipeline = new Map<
152	      string,
153	      LLMChatPipeline | EmbeddingPipeline
154	    >();
155	    this.loadedModelIdToChatConfig = new Map<string, ChatConfig>();
156	    this.loadedModelIdToModelType = new Map<string, ModelType>();
157	    this.loadedModelIdToLock = new Map<string, CustomLock>();
158	    this.appConfig = engineConfig?.appConfig || prebuiltAppConfig;
159	    this.setLogLevel(engineConfig?.logLevel || DefaultLogLevel);
160	    this.setInitProgressCallback(engineConfig?.initProgressCallback);
161	    this.setLogitProcessorRegistry(engineConfig?.logitProcessorRegistry);
162	
163	    this.chat = new API.Chat(this);
164	    this.completions = new API.Completions(this);
165	    this.embeddings = new API.Embeddings(this);
166	  }
167	
168	  //-----------------------
169	  // 0. Setters and getters
170	  //-----------------------
171	
172	  setAppConfig(appConfig: AppConfig) {
173	    this.appConfig = appConfig;
174	  }
175	
176	  setInitProgressCallback(initProgressCallback?: InitProgressCallback) {
177	    this.initProgressCallback = initProgressCallback;
178	  }
179	
180	  getInitProgressCallback() {
181	    return this.initProgressCallback;
182	  }
183	
184	  setLogitProcessorRegistry(
185	    logitProcessorRegistry?: Map<string, LogitProcessor>,
186	  ) {
187	    this.logitProcessorRegistry = logitProcessorRegistry;
188	  }
189	
190	  /**
191	   * Set MLCEngine logging output level
192	   *
193	   * @param logLevel The new log level
194	   */
195	  setLogLevel(logLevel: LogLevel) {
196	    log.setLevel(logLevel);
197	  }
198	
199	  //----------------------------------------
200	  // 1. Model/pipeline loading and unloading
201	  //----------------------------------------
202	
203	  async reload(
204	    modelId: string | string[],
205	    chatOpts?: ChatOptions | ChatOptions[],
206	  ): Promise<void> {
207	    // 0. Unload all loaded models
208	    await this.unload();
209	    // 1. Convert inputs to arrays
210	    if (!Array.isArray(modelId)) {
211	      modelId = [modelId];
212	    }
213	    if (chatOpts !== undefined && !Array.isArray(chatOpts)) {
214	      chatOpts = [chatOpts];
215	    }
216	    // 2. Check whether size matches
217	    if (chatOpts !== undefined && modelId.length !== chatOpts.length) {
218	      throw new ReloadArgumentSizeUnmatchedError(
219	        modelId.length,
220	        chatOpts.length,
221	      );
222	    }
223	    // 3. Make sure each model in modelId is unique
224	    if (new Set(modelId).size < modelId.length) {
225	      throw new ReloadModelIdNotUniqueError(modelId);
226	    }
227	    // 4. Sequentially load each model
228	    // Single abort should stop all to-be-loaded models
229	    this.reloadController = new AbortController();
230	    try {
231	      for (let i = 0; i < modelId.length; i++) {
232	        await this.reloadInternal(
233	          modelId[i],
234	          chatOpts ? chatOpts[i] : undefined,
235	        );
236	      }
237	    } catch (error) {
238	      if (error instanceof DOMException && error.name === "AbortError") {
239	        log.warn("Reload() is aborted.", error.message);
240	        return;
241	      }
242	      throw error;
243	    } finally {
244	      this.reloadController = undefined;
245	    }
246	  }
247	
248	  private async reloadInternal(
249	    modelId: string,
250	    chatOpts?: ChatOptions,
251	  ): Promise<void> {
252	    const logitProcessor = this.logitProcessorRegistry?.get(modelId);
253	    const tstart = performance.now();
254	
255	    // look up and parse model record, record model type
256	    const modelRecord = findModelRecord(modelId, this.appConfig);
257	    const baseUrl =
258	      typeof document !== "undefined"
259	        ? document.URL
260	        : globalThis.location.origin;
261	    let modelUrl = cleanModelUrl(modelRecord.model);
262	    if (!modelUrl.startsWith("http")) {
263	      modelUrl = new URL(modelUrl, baseUrl).href;
264	    }
265	    const modelType =
266	      modelRecord.model_type === undefined || modelRecord.model_type === null
267	        ? ModelType.LLM
268	        : modelRecord.model_type;
269	    this.loadedModelIdToModelType.set(modelId, modelType);
270	
271	    // instantiate cache
272	    const configCache = tvmjs.createArtifactCache(
273	      "webllm/config",
274	      getCacheOptions(this.appConfig),
275	    );
276	
277	    // load config
278	    const configUrl = new URL("mlc-chat-config.json", modelUrl).href;
279	    const configData = (await configCache.fetchWithCache(
280	      configUrl,
281	      "arraybuffer",
282	      this.reloadController?.signal,
283	    )) as ArrayBuffer;
284	    if (modelRecord.integrity?.config) {
285	      await verifyIntegrity(
286	        configData,
287	        modelRecord.integrity.config,
288	        configUrl,
289	        modelRecord.integrity.onFailure,
290	      );
291	    }
292	    const curModelConfig: ChatConfig = {
293	      ...JSON.parse(new TextDecoder().decode(configData)),
294	      ...modelRecord.overrides,
295	      ...chatOpts,
296	    } as ChatConfig;
297	    this.loadedModelIdToChatConfig.set(modelId, curModelConfig);
298	
299	    // load tvm wasm
300	    const wasmCache = tvmjs.createArtifactCache(
301	      "webllm/wasm",
302	      getCacheOptions(this.appConfig),
303	    );
304	
305	    const wasmUrl = modelRecord.model_lib;
306	    if (wasmUrl === undefined) {
307	      throw new MissingModelWasmError(modelRecord.model_id);
308	    }
309	    const fetchWasmSource = async () => {
310	      if (wasmUrl.includes("localhost")) {
311	        // do not cache wasm on local host as we might update code frequently
312	        return (await fetch(wasmUrl)).arrayBuffer();
313	      } else if (!wasmUrl.startsWith("http")) {
314	        // do not cache wasm on the same server as it can also refresh
315	        // rely on the normal caching strategy
316	        return (await fetch(new URL(wasmUrl, baseUrl).href)).arrayBuffer();
317	      } else {
318	        return await wasmCache.fetchWithCache(
319	          wasmUrl,
320	          "arraybuffer",
321	          this.reloadController?.signal,
322	        );
323	      }
324	    };
325	    const wasmSource = await fetchWasmSource();
326	
327	    if (modelRecord.integrity?.model_lib) {
328	      await verifyIntegrity(
329	        wasmSource,
330	        modelRecord.integrity.model_lib,
331	        wasmUrl,
332	        modelRecord.integrity.onFailure,
333	      );
334	    }
335	
336	    const wasm = new Uint8Array(wasmSource);
337	    const tvm = await tvmjs.instantiate(
338	      wasm.buffer,
339	      tvmjs.createPolyfillWASI(),
340	      this.logger,
341	    );
342	
343	    if (this.initProgressCallback !== undefined) {
344	      tvm.registerInitProgressCallback(this.initProgressCallback);
345	    }
346	
347	    // detect GPU
348	    const gpuDetectOutput = await tvmjs.detectGPUDevice();
349	    if (gpuDetectOutput == undefined) {
350	      throw new WebGPUNotAvailableError();
351	    }
352	    let gpuLabel = "WebGPU";
353	    if (gpuDetectOutput.adapterInfo.description.length != 0) {
354	      gpuLabel += " - " + gpuDetectOutput.adapterInfo.description;
355	    } else {
356	      gpuLabel += " - " + gpuDetectOutput.adapterInfo.vendor;
357	    }
358	    if (modelRecord.required_features !== undefined) {
359	      for (const feature of modelRecord.required_features) {
360	        if (!gpuDetectOutput.device.features.has(feature)) {
361	          if (feature == "shader-f16") {
362	            throw new ShaderF16SupportError();
363	          }
364	          throw new FeatureSupportError(feature);
365	        }
366	      }
367	    }
368	
369	    // Most device lost happens in `reload()` since we allocate memory ahead of time. So we can
370	    // use this flag at the end of `reload()` to make the error handling synchronous.
371	    // This `.then()` exists throughout the lifetime of the device. Though we have not
372	    // experienced device error outside of `reload()`, it is still possible this `.then()` is
373	    // triggered outside of `reload()`. TODO: does this cause unexpected behavior?
374	    let deviceLostInReload = false;
375	    gpuDetectOutput.device.lost.then((info: any) => {
376	      if (this.deviceLostIsError) {
377	        log.error(
378	          `Device was lost. This can happen due to insufficient memory or other GPU constraints. ` +
379	            `Detailed error: ${info}. Please try to reload WebLLM with a less resource-intensive model.`,
380	        );
381	        this.unload();
382	        deviceLostInReload = true;
383	      }
384	    });
385	    tvm.initWebGPU(gpuDetectOutput.device);
386	
387	    const tokenizer = await asyncLoadTokenizer(
388	      modelUrl,
389	      curModelConfig,
390	      this.appConfig,
391	      this.logger,
392	      modelRecord.integrity,
393	    );
394	    await tvm.fetchTensorCache(modelUrl, tvm.webgpu(), {
395	      ...getTensorCacheAccessOptions("webllm/model", this.appConfig),
396	      signal: this.reloadController?.signal,
397	    });
398	
399	    // Instantiate pipeline
400	    // TODO: would be good to somehow check for error when LLMChatPipeline is loaded for an
401	    // embedding model, and prompt user to use ModelRecord.model_type
402	    let newPipeline: LLMChatPipeline | EmbeddingPipeline;
403	    if (modelRecord.model_type === ModelType.embedding) {
404	      newPipeline = new EmbeddingPipeline(tvm, tokenizer, curModelConfig);
405	    } else {
406	      newPipeline = new LLMChatPipeline(
407	        tvm,
408	        tokenizer,
409	        curModelConfig,
410	        logitProcessor,
411	      );
412	    }
413	    await newPipeline.asyncLoadWebGPUPipelines();
414	    this.loadedModelIdToPipeline.set(modelId, newPipeline);
415	    this.loadedModelIdToLock.set(modelId, new CustomLock());
416	
417	    // Clean up
418	    const tend = performance.now();
419	    if (this.initProgressCallback !== undefined) {
420	      const text = "Finish loading on " + gpuLabel;
421	      this.initProgressCallback({
422	        progress: 1,
423	        timeElapsed: (tend - tstart) / 1e3,
424	        text: text,
425	      });
426	    }
427	    if (deviceLostInReload) {
428	      throw new DeviceLostError();
429	    }
430	  }
431	
432	  async unload() {
433	    this.deviceLostIsError = false; // so that unload() does not trigger device.lost error
434	    // TODO: can optimize by calling dispose() to all pipelines in parallel. However, need to wait
435	    // for all sync() to finish before proceeding (e.g. naive forEach does not work)
436	    for (const entry of Array.from(this.loadedModelIdToPipeline.entries())) {
437	      const pipeline = entry[1];
438	      pipeline.dispose();
439	      // Wait until device is actually destroyed so we can safely set deviceLostIsError back to true
440	      await pipeline.sync();
441	    }
442	    this.loadedModelIdToPipeline.clear();
443	    this.loadedModelIdToChatConfig.clear();
444	    this.loadedModelIdToModelType.clear();
445	    this.loadedModelIdToLock.clear();
446	    this.deviceLostIsError = true;
447	    if (this.reloadController) {
448	      this.reloadController.abort("Engine.unload() is called.");
449	      this.reloadController = undefined;
450	    }
451	  }
452	
453	  //---------------------------------------------------
454	  // 2. Underlying auto-regressive generation functions
455	  //---------------------------------------------------
456	
457	  private async _generate(
458	    input:
459	      | ChatCompletionRequestNonStreaming
460	      | CompletionCreateParamsNonStreaming,
461	    pipeline: LLMChatPipeline,
462	    chatConfig: ChatConfig,
463	    genConfig: GenerationConfig,
464	  ): Promise<string> {
465	    this.interruptSignal = false;
466	    if (genConfig !== undefined) {
467	      postInitAndCheckGenerationConfigValues(genConfig);
468	    }
469	    await this.prefill(input, pipeline, chatConfig, genConfig);
470	
471	    while (!pipeline.stopped()) {
472	      if (this.interruptSignal) {
473	        pipeline.triggerStop();
474	        break;
475	      }
476	      await this.decode(pipeline, genConfig);
477	    }
478	    return pipeline.getMessage();
479	  }
480	
481	  /**
482	   * Similar to `_generate()`; but instead of using callback, we use an async iterable.
483	   */
484	  asyncGenerate(
485	    request: ChatCompletionRequestStreaming,
486	    model: string,
487	    pipeline: LLMChatPipeline,
488	    chatConfig: ChatConfig,
489	    genConfig: GenerationConfig,
490	    timeReceived: number,
491	  ): AsyncGenerator<ChatCompletionChunk, void, void>;
492	  asyncGenerate(
493	    request: CompletionCreateParamsStreaming,
494	    model: string,
495	    pipeline: LLMChatPipeline,
496	    chatConfig: ChatConfig,
497	    genConfig: GenerationConfig,
498	    timeReceived: number,
499	  ): AsyncGenerator<Completion, void, void>;
500	  async *asyncGenerate(
501	    request: ChatCompletionRequestStreaming | CompletionCreateParamsStreaming,
502	    model: string,
503	    pipeline: LLMChatPipeline,
504	    chatConfig: ChatConfig,
505	    genConfig: GenerationConfig,
506	    timeReceived: number,
507	  ): AsyncGenerator<ChatCompletionChunk | Completion, void, void> {
508	    // Since it is an async generator, we need to do fine-grained try-catch to ensure lock is
509	    // released only when errors occur. Then release at the very end when no error occurs.
510	    // TODO: This makes code less readable, is there a better way to do this?
511	    const lock = this.loadedModelIdToLock.get(model)!;
512	
513	    // 0. Pre-processing
514	    const isChatCompletion = "messages" in request;
515	    const isFunctionCalling =
516	      "tools" in request &&
517	      request.tools !== undefined &&
518	      request.tools !== null;
519	    try {
520	      if (isFunctionCalling && !isChatCompletion) {
521	        throw new Error(
522	          "Expect `chat.completions` with tools, not `completions`.",
523	        );
524	      }
525	      postInitAndCheckGenerationConfigValues(genConfig);
526	      if (request.seed !== null && request.seed !== undefined) {
527	        pipeline.setSeed(request.seed);
528	      }
529	    } catch (err) {
530	      await lock.release();
531	      throw err;
532	    }
533	
534	    // 1. Helper function that generates the chunk
535	    const created = getUnixTimestampSeconds();
536	    const id = crypto.randomUUID();
537	    this.interruptSignal = false;
538	    let prevMessageLength = 0; // to know where to start slicing the delta; does not count �
539	
540	    function _countTrailingReplacementChar(curMessage: string): number {
541	      let cntr = 0;
542	      for (let i = curMessage.length - 1; i >= 0; i--) {
543	        if (curMessage.charAt(i) === "�") {
544	          cntr += 1;
545	        } else {
546	          return cntr;
547	        }
548	      }
549	      return cntr;
550	    }
551	
552	    async function _getChunk(
553	      selectedPipeline: LLMChatPipeline,
554	    ): Promise<ChatCompletionChunk | Completion | undefined> {
555	      // Remove the replacement character (U+FFFD) from the response to handle emojis.
556	      // Each emoji is made up of multiples of 4 tokens; when truncated, it is displayed as �, so
557	      // we skip this delta until a full emoji is rendered
558	      // TODO(Charlie): This does not consider cases of � not being emoji, need to fix with Streamer
559	      const curMessage = selectedPipeline.getMessage();
560	      const numTrailingReplacementChar =
561	        _countTrailingReplacementChar(curMessage);
562	      if (numTrailingReplacementChar % 4 !== 0) {
563	        return undefined;
564	      }
565	
566	      const deltaMessage = curMessage.slice(prevMessageLength);
567	      prevMessageLength = curMessage.length;
568	      const logprobs = request.logprobs
569	        ? ({
570	            content: selectedPipeline.getTokenLogprobArray().slice(-1), // always the last entry
571	          } as ChatCompletionChunk.Choice.Logprobs)
572	        : null;
573	      if (isChatCompletion) {
574	        const chunk: ChatCompletionChunk = {
575	          id: id,
576	          choices: [
577	            {
578	              delta: { content: deltaMessage, role: "assistant" },
579	              finish_reason: null, // not finished yet
580	              index: 0,
581	              logprobs: logprobs,
582	            },
583	          ],
584	          model: model,
585	          object: "chat.completion.chunk",
586	          created: created,
587	        };
588	        return chunk;
589	      } else {
590	        const chunk: Completion = {
591	          id: id,
592	          choices: [
593	            {
594	              text: deltaMessage,
595	              finish_reason: null, // not finished yet
596	              index: 0,
597	              logprobs: logprobs,
598	            },
599	          ],
600	          model: model,
601	          object: "text_completion",
602	          created: created,
603	        };
604	        return chunk;
605	      }
606	    }
607	
608	    // 2. Auto-regressive loop
609	    let curChunk;
610	    try {
611	      await this.prefill(request, pipeline, chatConfig, genConfig);
612	      curChunk = await _getChunk(pipeline); // prefill produces a chunk
613	    } catch (err) {
614	      await lock.release();
615	      throw err;
616	    }
617	    if (curChunk) {
618	      yield curChunk;
619	    }
620	
621	    while (!pipeline.stopped()) {
622	      if (this.interruptSignal) {
623	        // TODO: should we directly release lock here and return the async
624	        // generator? Though no issue observed as of now with interruptGenerate()
625	        pipeline.triggerStop();
626	        break;
627	      }
628	      try {
629	        await this.decode(pipeline, genConfig);
630	        curChunk = await _getChunk(pipeline);
631	      } catch (err) {
632	        await lock.release();
633	        throw err;
634	      }
635	      if (curChunk) {
636	        yield curChunk;
637	      }
638	    }
639	
640	    // Reset seed -- we do not want this seed to affect future requests
641	    if (request.seed !== null && request.seed !== undefined) {
642	      pipeline.setSeed(Date.now());
643	    }
644	
645	    // 3. Last chunk empty marking the end
646	    // If function calling, use the last chunk to return tool_calls
647	    let finish_reason = pipeline.getFinishReason()!;
648	    let tool_calls:
649	      | Array<ChatCompletionChunk.Choice.Delta.ToolCall>
650	      | undefined;
651	    try {
652	      if (pipeline.getFinishReason() === "stop" && isFunctionCalling) {
653	        // If stopped due to length or abort, cannot output return tool_calls field
654	        finish_reason = "tool_calls";
655	        const outputMessage = pipeline.getMessage();
656	        tool_calls = getToolCallFromOutputMessage(
657	          outputMessage,
658	          /*isStreaming=*/ true,
659	        ) as Array<ChatCompletionChunk.Choice.Delta.ToolCall>;
660	      }
661	    } catch (err) {
662	      await lock.release();
663	      throw err;
664	    }
665	
666	    if (isChatCompletion) {
667	      const lastChunk: ChatCompletionChunk = {
668	        id: id,
669	        choices: [
670	          {
671	            delta: isFunctionCalling
672	              ? {
673	                  role: "assistant",
674	                  tool_calls: tool_calls,
675	                }
676	              : {},
677	            finish_reason: finish_reason,
678	            index: 0,
679	          },
680	        ],
681	        model: model,
682	        object: "chat.completion.chunk",
683	        created: created,
684	      };
685	      yield lastChunk;
686	    } else {
687	      const lastChunk: Completion = {
688	        id: id,
689	        choices: [
690	          {
691	            text: "",
692	            finish_reason: finish_reason,
693	            index: 0,
694	          },
695	        ],
696	        model: model,
697	        object: "text_completion",
698	        created: created,
699	      };
700	      yield lastChunk;
701	    }
702	
703	    // 4. Usage chunk
704	    if (request.stream_options?.include_usage) {
705	      const usedGrammar =
706	        "response_format" in request &&
707	        (request.response_format?.type === "grammar" ||
708	          request.response_format?.type === "json_object");
709	      const completion_tokens = pipeline.getCurRoundDecodingTotalTokens();
710	      const prompt_tokens = pipeline.getCurRoundPrefillTotalTokens();
711	      const prefill_tokens_per_s = pipeline.getCurRoundPrefillTokensPerSec();
712	      const decode_tokens_per_s = pipeline.getCurRoundDecodingTokensPerSec();
713	      const grammar_init_s = pipeline.getCurRoundGrammarInitTotalTime();
714	      const prefill_time = pipeline.getCurRoundPrefillTotalTime();
715	      const decode_time = pipeline.getCurRoundDecodingTotalTime();
716	      const grammar_per_token_s =
717	        pipeline.getCurRoundGrammarPerTokenTotalTime();
718	      const latencyBreakdown: LatencyBreakdown =
719	        pipeline.getCurRoundLatencyBreakdown();
720	
721	      const defaultExtra = {
722	        e2e_latency_s: (Date.now() - timeReceived) / 1000,
723	        prefill_tokens_per_s: prefill_tokens_per_s,
724	        decode_tokens_per_s: decode_tokens_per_s,
725	        time_to_first_token_s: prefill_time,
726	        time_per_output_token_s: decode_time / completion_tokens,
727	        latencyBreakdown: request.extra_body?.enable_latency_breakdown
728	          ? latencyBreakdown
729	          : undefined,
730	      };
731	      const usage: CompletionUsage = {
732	        completion_tokens: completion_tokens,
733	        prompt_tokens: prompt_tokens,
734	        total_tokens: completion_tokens + prompt_tokens,
735	        extra: usedGrammar
736	          ? {
737	              ...defaultExtra,
738	              ...{
739	                grammar_init_s: grammar_init_s,
740	                grammar_per_token_s: grammar_per_token_s / completion_tokens,
741	              },
742	            }
743	          : defaultExtra,
744	      };
745	      if (isChatCompletion) {
746	        const usageChunk: ChatCompletionChunk = {
747	          id: id,
748	          choices: [],
749	          usage: usage,
750	          model: model,
751	          object: "chat.completion.chunk",
752	          created: created,
753	        };
754	        yield usageChunk;
755	      } else {
756	        const usageChunk: Completion = {
757	          id: id,
758	          choices: [],
759	          usage: usage,
760	          model: model,
761	          object: "text_completion",
762	          created: created,
763	        };
764	        yield usageChunk;
765	      }
766	    }
767	
768	    await lock.release();
769	  }
