1298	    const [, selectedPipeline] = this.getLLMStates(
1299	      "forwardTokensAndSample",
1300	      modelId,
1301	    );
1302	    return selectedPipeline.forwardTokensAndSample(inputIds, isPrefill);
1303	  }
1304	
1305	  /**
1306	   * Get the current generated response.
1307	   *
1308	   * @returns The current output message.
1309	   */
1310	  async getMessage(modelId?: string): Promise<string> {
1311	    const [, selectedPipeline] = this.getLLMStates("getMessage", modelId);
1312	    return selectedPipeline.getMessage();
1313	  }
1314	
1315	  async runtimeStatsText(modelId?: string): Promise<string> {
1316	    log.warn(
1317	      "WARNING: `runtimeStatsText()` will soon be deprecated. " +
1318	        "Please use `ChatCompletion.usage` for non-streaming requests, or " +
1319	        "`ChatCompletionChunk.usage` for streaming requests, enabled by `stream_options`. " +
1320	        "The only flow that expects to use `runtimeStatsText()` as of now is `forwardTokensAndSample()`.",
1321	    );
1322	    const [, selectedPipeline] = this.getLLMStates("runtimeStatsText", modelId);
1323	    return selectedPipeline.runtimeStatsText();
1324	  }
1325	
1326	  async resetChat(keepStats = false, modelId?: string) {
1327	    try {
1328	      const [, selectedPipeline] = this.getLLMStates("resetChat", modelId);
1329	      selectedPipeline.resetChat(keepStats);
1330	    } catch (error) {
1331	      if (
1332	        error instanceof ModelNotLoadedError ||
1333	        error instanceof SpecifiedModelNotFoundError
1334	      ) {
1335	        // Only allow calling resetChat before pipeline instantiated.
1336	        log.debug(
1337	          "Caught an expected error in resetChat, treating it as no-op. Error: ",
1338	          error,
1339	        );
1340	      } else {
1341	        throw error;
1342	      }
1343	    }
1344	  }
1345	
1346	  //-----------------------------------------------
1347	  // 7. Prefill and decode given an LLMChatPipeline
1348	  //-----------------------------------------------
1349	
1350	  /**
1351	   * Run a prefill step with a given input.
1352	   *
1353	   * If `input` is a chatCompletionRequest, we treat `input.messages[-1]` as the usual user input.
1354	   * We then convert `input.messages[:-1]` to a `Conversation` object, representing a conversation
1355	   * history.
1356	   *
1357	   * If the new `Conversation` object matches the current one loaded, it means we are
1358	   * performing multi-round chatting, so we do not reset, hence reusing KV cache. Otherwise, we
1359	   * reset every thing, treating the request as something completely new.
1360	   *
1361	   * @param input The OpenAI-style prompt to prefill.
1362	   * @param pipeline The loaded pipeline, hence model, to carry out this prefill.
1363	   * @param chatConfig The chat config to use for this model.
1364	   * @param genConfig Generation config.
1365	   */
1366	  async prefill(
1367	    input: ChatCompletionRequest | CompletionCreateParams,
1368	    pipeline: LLMChatPipeline,
1369	    chatConfig: ChatConfig,
1370	    genConfig: GenerationConfig,
1371	  ) {
1372	    // TODO: SPECIFY MODEL TO PERFORM PREFILL, HENCE RETRIEVE CONFIG
1373	    if (chatConfig === undefined) {
1374	      throw new ConfigurationNotInitializedError();
1375	    }
1376	    let input_str: string;
1377	    let input_role_str: string | undefined;
1378	    let lastMsgRole = Role.user;
1379	    if ("messages" in input) {
1380	      // For ChatCompletionRequest, we prepare input using `messages`
1381	      // 1. Get new conversation based on request, determine if we are in multiround chatting
1382	      const oldConv = pipeline.getConversationObject();
1383	      const newConv = getConversationFromChatCompletionRequest(
1384	        input,
1385	        chatConfig,
1386	      );
1387	      if (!compareConversationObject(oldConv, newConv)) {
1388	        // Not the same conversation, so not multiround chatting, reset everything (KV cache, etc.)
1389	        pipeline.resetChat();
1390	        pipeline.setConversation(newConv);
1391	      } else if (newConv.messages.length === 0) {
1392	        // Empty oldConv, and no chat history in newConv, so reset and setConversation
1393	        pipeline.resetChat();
1394	        pipeline.setConversation(newConv);
1395	      } else {
1396	        log.info("Multiround chatting, reuse KVCache.");
1397	      }
