1399	      // 2. Treat the last message as the usual input
1400	      const last_msg = input.messages[
1401	        input.messages.length - 1
1402	      ] as ChatCompletionMessageParam;
1403	      input_str = last_msg.content as string;
1404	      input_role_str =
1405	        last_msg.role === "user" && last_msg.name ? last_msg.name : undefined;
1406	      lastMsgRole = last_msg.role === "tool" ? Role.tool : Role.user;
1407	    } else {
